unsigned int bm_get(Bitmap *b, int x, int y) { /* <=== bm_get */ 
    unsigned int *p;
    assert(x >= 0 && x < b->w && y >= 0 && y < b->h);
    p = (unsigned int*)(b->data + y * BM_ROW_SIZE(b) + x * BM_BPP);
    return *p;
}

